30	const PROCESSING_FEE = 5;
31	
32	/**
33	 * The spec keeps intermediate amounts as exact fractions and rounds only the
34	 * final amount. Binary floating point cannot do that: `100 * 1.1` is
35	 * 110.00000000000001, which rounds *up* to 111 instead of 110.
36	 *
37	 * So percentages are applied as integer rationals — multiply by the numerator
38	 * first, divide by the denominator last — and money is carried in hundredths
39	 * of a G. Both operands of every product stay integral, so no drift accrues.
40	 */
41	const SUBUNITS_PER_G = 100;
42	const toSubunits = (gold: number): number => Math.round(gold * SUBUNITS_PER_G);
43	
44	/** A percentage as an exact rational, e.g. +10 % is { num: 110, den: 100 }. */
45	interface Rate {
46	  num: number;
47	  den: number;
48	}
49	
50	const FIRST_INSURANCE_SURCHARGE: Rate = { num: 110, den: 100 };
51	
52	const applyRate = (subunits: number, rate: Rate): number => (subunits * rate.num) / rate.den;
53	
54	/** Premiums round up — in the MHPCO's favour. */
55	const toPremiumGold = (subunits: number): number => Math.ceil(subunits / SUBUNITS_PER_G);
56	
57	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
58	  sword: 100,
59	  amulet: 60,
60	  staff: 80,
61	  potion: 40,
62	  rune: 25,
63	  moonstone: 25,
64	};
65	
66	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_ITEM_TYPE[item.type] ?? 0;
67	
68	const COMPONENT_TYPES = ["rune", "moonstone"];
69	
70	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
71	
72	/** Exactly this many alike components form a block, priced as one unit. */
73	const COMPONENT_BLOCK_SIZE = 3;
74	const COMPONENT_BLOCK_PREMIUM = 60;
75	
76	const countByType = (items: Item[]): Map<string, number> => {
77	  const counts = new Map<string, number>();
78	  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
79	
80	  return counts;
81	};
82	
83	/**
84	 * Alike components — those of the very same type — form a block when there are
85	 * exactly COMPONENT_BLOCK_SIZE of them; the block is priced as one unit.
86	 * Any other count is priced per component.
87	 */
88	const componentGroupPremium = (type: string, count: number): number =>
89	  count === COMPONENT_BLOCK_SIZE
90	    ? COMPONENT_BLOCK_PREMIUM
91	    : count * (BASE_PREMIUM_BY_ITEM_TYPE[type] ?? 0);
92	
93	const sumOfBasePremiums = (items: Item[]): number =>
94	  items.reduce((total, item) => total + basePremiumOf(item), 0);
95	
96	/**
97	 * The policy base premium: every insured item's base premium, summed — except
98	 * that each group of alike components is priced as blocks where it can be.
99	 */
100	const policyBasePremiumOf = (items: Item[]): number => {
101	  const components = items.filter(isComponent);
102	  const componentsTotal = [...countByType(components)].reduce(
103	    (total, [type, count]) => total + componentGroupPremium(type, count),
104	    0,
105	  );
106	
107	  return sumOfBasePremiums(items.filter((item) => !isComponent(item))) + componentsTotal;
108	};
109	
110	const quotePremium = (items: Item[]): number => {
111	  const policyBase = toSubunits(policyBasePremiumOf(items));
112	
113	  return toPremiumGold(applyRate(policyBase, FIRST_INSURANCE_SURCHARGE) + toSubunits(PROCESSING_FEE));
114	};
115	
116	export const runScenario = (scenario: Scenario): ScenarioResults => {
117	  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
118	};
